// H1b — enrich one lead: crawl ≤5 pages, extract emails/socials, audit, MX check.
// Free sources only. Optional: PageSpeed (PAGESPEED_API_KEY), Companies House (COMPANIES_HOUSE_API_KEY).
// The n8n code sandbox has no global URL; use Node's.
const { URL } = require('url');
// Enrich several leads at once (each mostly waits on the network: crawl,
// DNS, PageSpeed up to 60 s), instead of one after another.
const CONCURRENCY = Number($env.ENRICH_CONCURRENCY || 6);
const enrichOne = async (lead) => {
  const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124 Safari/537.36';
  const http = (opts) => this.helpers.httpRequest({ timeout: 10000, headers: { 'User-Agent': UA, Accept: 'text/html,*/*' }, returnFullResponse: true, ignoreHttpStatusErrors: true, ...opts });

  const issues = [];
  const audit = { url: null, reachable: false, hasSsl: null, mobileFriendly: null, techStack: [], emailsFound: [], socials: {}, issues };
  let email; let emailStatus; let companyType;

  function normUrl(u) {
    if (!u) return null;
    let s = String(u).trim();
    if (!/^https?:\/\//i.test(s)) s = 'https://' + s;
    try { const x = new URL(s); x.hash = ''; return x; } catch { return null; }
  }
  const siteDomain = (h) => h.replace(/^www\./i, '').toLowerCase();

  const start = normUrl(lead.website);
  if (start) {
    audit.url = start.origin;
    const pages = [];
    let home = null;
    try {
      home = await http({ url: start.href });
      if (home.statusCode >= 200 && home.statusCode < 400 && typeof home.body === 'string') {
        audit.reachable = true; pages.push(home.body);
      }
    } catch { /* unreachable over https */ }
    if (!audit.reachable && start.protocol === 'https:') {
      try {
        const h2 = await http({ url: start.href.replace(/^https:/, 'http:') });
        if (h2.statusCode < 400 && typeof h2.body === 'string') { audit.reachable = true; home = h2; pages.push(h2.body); audit.hasSsl = false; }
      } catch { /* ignore */ }
    }
    if (audit.reachable && audit.hasSsl === null) audit.hasSsl = start.protocol === 'https:';

    if (audit.reachable) {
      const html0 = pages[0];
      // Likely contact pages from the homepage links, max 4 extra.
      const links = [...html0.matchAll(/href\s*=\s*["']([^"'#]+)["']/gi)].map((m) => m[1]);
      const wanted = [];
      for (const l of links) {
        if (!/contact|about|team|impressum|get-in-touch|reach/i.test(l)) continue;
        try { const u = new URL(l, start.origin); if (siteDomain(u.hostname) === siteDomain(start.hostname) && !wanted.includes(u.href)) wanted.push(u.href); } catch {}
      }
      for (const p of ['/contact', '/contact-us', '/about']) { const u = start.origin + p; if (!wanted.includes(u)) wanted.push(u); }
      for (const u of wanted.slice(0, 4)) {
        try { const r = await http({ url: u }); if (r.statusCode < 400 && typeof r.body === 'string') pages.push(r.body); } catch {}
      }

      const all = pages.join('\n');
      // Emails: plain text + mailto, with obfuscation like "name [at] domain [dot] com".
      const deob = all.replace(/\s*(\[|\()\s*at\s*(\]|\))\s*/gi, '@').replace(/\s*(\[|\()\s*dot\s*(\]|\))\s*/gi, '.');
      const found = new Set();
      for (const m of deob.matchAll(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,24}/gi)) {
        const e = m[0].toLowerCase().replace(/^\.+|\.+$/g, '');
        if (/\.(png|jpe?g|gif|svg|webp|avif|css|js)$/.test(e)) continue;
        if (/(example|domain|yourdomain|email|sentry|wixpress|godaddy|squarespace)\.(com|io|org)$/.test(e)) continue;
        if (/^(user|name|your|john|jane|test)@/.test(e)) continue;
        if (e.length > 80) continue;
        found.add(e);
      }
      const dom = siteDomain(start.hostname);
      const ranked = [...found].sort((a, b) => {
        const s = (e) => (e.endsWith('@' + dom) || e.endsWith('.' + dom) ? 0 : 2) + (/^(noreply|no-reply|donotreply)/.test(e) ? 5 : 0) + (/^(info|hello|contact|office|enquiries|sales)@/.test(e) ? 1 : 0);
        return s(a) - s(b);
      });
      audit.emailsFound = ranked.slice(0, 10);
      email = ranked.find((e) => !/^(noreply|no-reply|donotreply)/.test(e));

      for (const [k, re] of Object.entries({
        facebook: /https?:\/\/(www\.)?facebook\.com\/[A-Za-z0-9_.\-\/]+/i,
        instagram: /https?:\/\/(www\.)?instagram\.com\/[A-Za-z0-9_.\-]+/i,
        linkedin: /https?:\/\/([a-z]+\.)?linkedin\.com\/(company|in)\/[A-Za-z0-9_\-%]+/i,
        x: /https?:\/\/(www\.)?(twitter|x)\.com\/[A-Za-z0-9_]+/i,
        youtube: /https?:\/\/(www\.)?youtube\.com\/[A-Za-z0-9_@\-\/]+/i,
        tiktok: /https?:\/\/(www\.)?tiktok\.com\/@[A-Za-z0-9_.]+/i,
      })) {
        // Skip tracking pixels / share buttons, keep the first real profile link.
        const g = new RegExp(re.source, 'gi');
        const hit = (all.match(g) || []).find((u) => !/\/(tr|sharer|share|plugins|dialog|intent|embed|watch|hashtag)([\/?]|$)|sharer\.php/i.test(u));
        if (hit) audit.socials[k] = hit.replace(/[\/]+$/, '');
      }

      const t = audit.techStack;
      const tech = { WordPress: /wp-content|wp-includes/i, Wix: /wix\.com|wixstatic/i, Squarespace: /squarespace/i, Shopify: /cdn\.shopify|myshopify/i,
        Webflow: /webflow/i, GoDaddy: /godaddy|wsimg\.com/i, Weebly: /weebly/i, Joomla: /joomla/i, Drupal: /drupal/i, Duda: /dudaone|multiscreensite/i,
        React: /__next|react-dom|data-reactroot/i, jQuery: /jquery/i, Bootstrap: /bootstrap(\.min)?\.css/i, 'Google Analytics': /gtag\(|google-analytics\.com|googletagmanager/i };
      for (const [name, re] of Object.entries(tech)) if (re.test(html0)) t.push(name);

      audit.mobileFriendly = /<meta[^>]+name=["']viewport["']/i.test(html0);
      if (!audit.mobileFriendly) issues.push('no-viewport');
      if (audit.hasSsl === false) issues.push('no-ssl');
      if (!/<title>[^<]{3,}<\/title>/i.test(html0)) issues.push('no-title');
      if (!/<meta[^>]+name=["']description["']/i.test(html0)) issues.push('no-meta-description');
      const years = [...html0.matchAll(/(?:©|&copy;|copyright)\s*(?:\d{4}\s*[-–]\s*)?(\d{4})/gi)].map((m) => Number(m[1]));
      if (years.length && Math.max(...years) < new Date().getFullYear() - 2) issues.push('stale-copyright');
      if (html0.length > 2_500_000) issues.push('heavy-page');
      if (!email) issues.push('no-email-found');
    } else {
      issues.push('unreachable');
    }
  } else {
    issues.push('no-website');
  }

  // MX check (DNS-over-HTTPS, free). Catch-all detection needs SMTP; not done.
  if (email) {
    try {
      const d = email.split('@')[1];
      const r = await this.helpers.httpRequest({ url: `https://dns.google/resolve?name=${encodeURIComponent(d)}&type=MX`, json: true, timeout: 8000 });
      const hasMx = Array.isArray(r.Answer) && r.Answer.some((a) => a.type === 15);
      emailStatus = hasMx ? (/^(info|hello|contact|office|enquiries|sales|admin)@/.test(email) ? 'risky' : 'valid') : 'invalid';
      if (!hasMx) issues.push('email-no-mx');
    } catch { emailStatus = 'unknown'; }
  }

  // Optional: Google PageSpeed (mobile). Free key; skipped when not configured.
  if (audit.reachable && $env.PAGESPEED_API_KEY) {
    try {
      const r = await this.helpers.httpRequest({ url: `https://www.googleapis.com/pagespeedonline/v5/runPagespeed?url=${encodeURIComponent(audit.url)}&strategy=mobile&category=performance&key=${$env.PAGESPEED_API_KEY}`, json: true, timeout: 60000 });
      const lh = r.lighthouseResult;
      audit.mobileScore = Math.round((lh?.categories?.performance?.score ?? 0) * 100);
      audit.lcpMs = Math.round(lh?.audits?.['largest-contentful-paint']?.numericValue ?? 0) || undefined;
      if (audit.mobileScore < 50) issues.push('slow-mobile');
    } catch { /* PSI is best effort */ }
  }

  // Optional: UK Companies House (free key). Company type by name search.
  if (['GB', 'UK'].includes(String(lead.country).toUpperCase()) && $env.COMPANIES_HOUSE_API_KEY && lead.name) {
    try {
      const r = await this.helpers.httpRequest({ url: `https://api.company-information.service.gov.uk/search/companies?items_per_page=1&q=${encodeURIComponent(lead.name)}`,
        json: true, timeout: 8000, auth: { username: $env.COMPANIES_HOUSE_API_KEY, password: '' } });
      const c = r.items?.[0];
      const map = { ltd: 'ltd', 'private-limited-guarant-nsc': 'ltd', 'private-unlimited': 'ltd', llp: 'llp', plc: 'plc' };
      if (c && c.company_status === 'active') companyType = map[c.company_type] ?? 'unknown';
    } catch { /* best effort */ }
  }

  const body = { workspaceId: lead.workspaceId || $env.KLYRO_WORKSPACE_ID, leadId: String(lead.leadId), audit };
  if (email) { body.email = email; body.emailStatus = emailStatus || 'unknown'; }
  if (companyType) body.companyType = companyType;
  return { json: { method: 'POST', path: '/internal/leads/enrichment', idempotencyKey: `enrich-${lead.leadId}-${lead.runId || Date.now()}`, body } };
};

const items = $input.all().map((i) => i.json);
const out = new Array(items.length);
let next = 0;
const worker = async () => {
  while (next < items.length) {
    const i = next++;
    try { out[i] = await enrichOne(items[i]); } catch (e) { out[i] = { json: { error: String(e?.message || e) } }; }
  }
};
await Promise.all(Array.from({ length: Math.min(CONCURRENCY, items.length) }, worker));
return out;
